// Generated by secure-by-design v0.1.0 for DPDP §9 (Children's data).
// Reads from ../../privacy-security-manifest.yaml.
// Safe to modify. Safe to delete. Re-run /sbd-deploy to regenerate.
// Docs: docs/scaffolds/children-gate.md
//
// Gates any code path that processes data of a data principal under 18.
// DPDP §9 requires VERIFIABLE parental consent; this scaffold provides the
// API shape but the actual verification provider is YOUR choice (e.g.
// DigiLocker, government-eID OTP, in-person, video KYC).
//
// THIS IS A SCAFFOLD. Do NOT ship to production without implementing a real
// parent-consent verification flow and having it reviewed by counsel.

import { auditLog } from '../security/audit_log';
import { recordConsent } from './consent';

export interface ParentalConsentVerifier {
  /**
   * Verify that the named parent/guardian has given consent for the specified child.
   * Implementation choices: DigiLocker / OTP-against-parent-Aadhaar-linked-mobile /
   * video-KYC by a registered practitioner / in-person at clinic.
   * Returns a verification token + the verified parent's identifier.
   */
  verify(input: {
    childDataPrincipalId: string;
    parentClaimedRelation: 'mother' | 'father' | 'legal-guardian';
    parentContact: string;        // PII — handle with care
    consentTextHash: string;
    noticeVersion: string;
  }): Promise<{
    verified: boolean;
    parentIdentifier?: string;    // pseudonymous (hash of govt-ID, not raw)
    method: string;               // e.g. 'digilocker', 'otp-aadhaar-linked', 'video-kyc'
    verifiedAt: Date;
  }>;
}

let verifier: ParentalConsentVerifier | null = null;
export function setParentalConsentVerifier(v: ParentalConsentVerifier): void {
  verifier = v;
}

export interface ChildContext {
  childDataPrincipalId: string;
  ageYears: number;          // computed from DOB by your auth layer
  purpose: string;           // specific purpose, e.g. 'patient.consultation.book'
  category: string;          // dataCategory name from manifest
  noticeVersion: string;
  consentTextHash: string;
  parentClaimedRelation: 'mother' | 'father' | 'legal-guardian';
  parentContact: string;
}

/**
 * Gate function — call BEFORE any storage / AI processing of children's data.
 * Throws if verifiable parental consent is not on file.
 *
 * DPDP §9(1) requires verifiable parental / lawful-guardian consent for
 * processing children's data. §9(2) prohibits tracking, behavioural monitoring,
 * and targeted advertising directed at children — those are out of scope here
 * and must be designed out of your product.
 */
export async function verifyParentalConsent(ctx: ChildContext): Promise<void> {
  if (ctx.ageYears >= 18) {
    // Adult — gate not applicable. The caller should have routed to standard consent.
    return;
  }

  if (!verifier) {
    throw new Error(
      'secure-by-design: ParentalConsentVerifier not configured. ' +
      'A children-data path requires DPDP §9 verifiable parental consent — wire up a verifier at boot.',
    );
  }

  const result = await verifier.verify({
    childDataPrincipalId: ctx.childDataPrincipalId,
    parentClaimedRelation: ctx.parentClaimedRelation,
    parentContact: ctx.parentContact,
    consentTextHash: ctx.consentTextHash,
    noticeVersion: ctx.noticeVersion,
  });

  if (!result.verified) {
    await auditLog.security('children.consent.denied', {
      target: ctx.childDataPrincipalId,
      severity: 'WARN',
      outcome: 'denied',
      attrs: { purpose: ctx.purpose, method: result.method },
    });
    const err: Error & { statusCode?: number; code?: string } = new Error(
      'DPDP §9: verifiable parental consent could not be established.',
    );
    err.statusCode = 451;
    err.code = 'PARENTAL_CONSENT_REQUIRED';
    throw err;
  }

  // Record alongside the standard consent chain so /dsr/access surfaces it.
  await recordConsent({
    dataPrincipalId: ctx.childDataPrincipalId,
    purpose: ctx.purpose,
    category: ctx.category,
    basis: 'explicit',
    noticeVersion: ctx.noticeVersion,
    consentTextHash: ctx.consentTextHash,
    language: 'en',
    givenByActor: 'parent-guardian',
    channel: 'web',
    expiresAt: null,
  });

  await auditLog.security('children.consent.recorded', {
    target: ctx.childDataPrincipalId,
    actor: result.parentIdentifier ?? 'parent:unknown',
    severity: 'NOTICE',
    outcome: 'success',
    attrs: { purpose: ctx.purpose, method: result.method, verifiedAt: result.verifiedAt.toISOString() },
  });
}

/**
 * Sentinel guard to use anywhere children's data MAY be processed.
 * Behavioural tracking, profiling, and targeted ads to children are prohibited
 * by §9(2) — this helper throws unconditionally if invoked on such a code path.
 */
export function refuseChildrenProfiling(reason: string): never {
  throw new Error(`DPDP §9(2) prohibits this for children: ${reason}`);
}
